// pqVectors is the part of pq-identity-vectors.json (generated by
// typescript/test/interops/generate-pq-identity-vectors.ts) checked here at the
// primitive level, including the exact DHIES v3 output.
type pqVectors struct {
	Identities map[string]struct {
		Algorithm       string `json:"algorithm"`
		Seed            string `json:"seed"`
		Secret          string `json:"secret"`
		CypherPublicKey string `json:"cypherPublicKey"`
		EK              string `json:"ek"`
		EKSha256        string `json:"ekSha256"`
		PRFKey          string `json:"prfKey"`
	} `json:"identities"`
	DHIESV3 []struct {
		Name               string `json:"name"`
		Sender             string `json:"sender"`
		Recipient          string `json:"recipient"`
		Plaintext          string `json:"plaintext"`
		EphemeralSecretKey string `json:"ephemeralSecretKey"`
		KEMRandomness      string `json:"kemRandomness"`
		Nonce              string `json:"nonce"`
		EphemeralPublicKey string `json:"ephemeralPublicKey"`
		KEMCiphertext      string `json:"kemCiphertext"`
		KSS                string `json:"kss"`
		Key                string `json:"key"`
		Out                string `json:"out"`
	} `json:"dhiesV3"`
}

func loadPQVectors(t *testing.T) pqVectors {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "test", "compatibility", "testdata", "pq-identity-vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v pqVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("invalid vectors JSON: %v", err)
	}
	return v
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// x25519SecretOf returns the X25519 secret of a vector identity: seed[32:64]
// for Dilithium and Hybrid, the `e` field of the secret for Ed25519.
func x25519SecretOf(t *testing.T, v pqVectors, name string) []byte {
	t.Helper()
	ident := v.Identities[name]
	if ident.Seed != "" {
		return unhex(t, ident.Seed)[32:64]
	}
	var secret struct {
		E []byte `msgpack:"e"`
	}
	if err := msgpack.Unmarshal(unhex(t, ident.Secret)[1:], &secret); err != nil || len(secret.E) != 32 {
		t.Fatalf("%s: cannot read the X25519 secret", name)
	}
	return secret.E
}

func TestPQKeyDerivationVectors(t *testing.T) {
	v := loadPQVectors(t)
	for name, ident := range v.Identities {
		if ident.Seed == "" {
			continue
		}
		seed := unhex(t, ident.Seed)
		ek, err := DeriveMLKEMPublicKey(seed)
		if err != nil {
			t.Fatal(err)
		}
		if hex.EncodeToString(ek) != ident.EK {
			t.Errorf("%s: ek mismatch", name)
		}
		prf, err := DerivePRFKey(seed)
		if err != nil {
			t.Fatal(err)
		}
		if hex.EncodeToString(prf) != ident.PRFKey {
			t.Errorf("%s: PRF key mismatch", name)
		}
	}
	if _, err := DeriveMLKEMPublicKey(make([]byte, 32)); err == nil {
		t.Error("a 32-byte seed must be rejected")
	}
}

func TestDHIESV3Vectors(t *testing.T) {
	v := loadPQVectors(t)
	if len(v.DHIESV3) == 0 {
		t.Fatal("no DHIES v3 vectors")
	}
	for _, c := range v.DHIESV3 {
		t.Run(c.Name, func(t *testing.T) {
			senderSecret := x25519SecretOf(t, v, c.Sender)
			senderPublic := unhex(t, v.Identities[c.Sender].CypherPublicKey)
			recipient := v.Identities[c.Recipient]
			recipientSeed := unhex(t, recipient.Seed)
			recipientPublic := unhex(t, recipient.CypherPublicKey)
			ek := unhex(t, recipient.EK)

			var nonce [dhiesNonceSize]byte
			copy(nonce[:], unhex(t, c.Nonce))
			out, err := dhiesEncryptV3Deterministic(unhex(t, c.EphemeralSecretKey), &nonce, unhex(t, c.KEMRandomness), senderSecret, senderPublic, recipientPublic, ek, unhex(t, c.Plaintext))
			if err != nil {
				t.Fatal(err)
			}
			if hex.EncodeToString(out) != c.Out {
				t.Fatal("DHIES v3 output differs from TypeScript")
			}

			// intermediate values, for diagnosis
			if hex.EncodeToString(out[25:57]) != c.EphemeralPublicKey || hex.EncodeToString(out[57:1145]) != c.KEMCiphertext {
				t.Fatal("e_pk or kem_ct mismatch")
			}
			pq := pqKeys{KEMPublicKey: ek}
			kss, err := pq.decapsulate(recipientSeed, out[57:1145])
			if err != nil || hex.EncodeToString(kss) != c.KSS {
				t.Fatal("kss mismatch")
			}
			es, _ := curve25519.X25519(recipientSeed[32:64], out[25:57])
			ss, _ := curve25519.X25519(recipientSeed[32:64], senderPublic)
			k := dhiesV3Key(es, ss, kss, out[25:57], senderPublic, recipientPublic, ek, out[57:1145])
			if hex.EncodeToString(k[:]) != c.Key {
				t.Fatal("k mismatch")
			}

			decapsulate := func(ct []byte) ([]byte, error) { return pq.decapsulate(recipientSeed, ct) }
			plaintext, err := DHIESDecryptV3(recipientSeed[32:64], recipientPublic, ek, decapsulate, senderPublic, unhex(t, c.Out))
			if err != nil || hex.EncodeToString(plaintext) != c.Plaintext {
				t.Fatal("cannot decrypt the TypeScript message")
			}
		})
	}
}

// newPQPair returns a sender (classical keys only) and a post-quantum recipient.
func newPQPair(t *testing.T) (senderSK, senderPK []byte, recipient *DilithiumManager) {
	t.Helper()
	sender, err := GenerateDilithiumInternal()
	if err != nil {
		t.Fatal(err)
	}
	recipient, err = GenerateDilithiumInternal()
	if err != nil {
		t.Fatal(err)
	}
	if err := recipient.EnablePostQuantum(); err != nil {
		t.Fatal(err)
	}
	return sender.Cypher.SecretKey, sender.Cypher.PublicKey, recipient
}

func TestDHIESV3RoundTripAndRejections(t *testing.T) {
	senderSK, senderPK, recipient := newPQPair(t)
	ek := recipient.GetKEMPublicKey()
	plaintext := []byte("post-quantum message")

	out, err := DHIESEncryptV3(senderSK, senderPK, recipient.Cypher.PublicKey, ek, plaintext)
	if err != nil {
		t.Fatal(err)
	}
	if len(out) != DHIESV3MinSize+len(plaintext) || DHIESV3MinSize != 1161 || out[0] != DHIESV3Version {
		t.Fatalf("unexpected layout: %d bytes", len(out))
	}
	open := func(msg, sender []byte) ([]byte, error) {
		return DHIESDecryptV3(recipient.Cypher.SecretKey, recipient.Cypher.PublicKey, ek, recipient.KEMDecapsulate, sender, msg)
	}
	got, err := open(out, senderPK)
	if err != nil || !bytes.Equal(got, plaintext) {
		t.Fatal("round trip failed")
	}

	other, _ := GenerateDilithiumInternal()
	if _, err := open(out, other.Cypher.PublicKey); err != ErrDHIESDecrypt {
		t.Error("wrong sender accepted")
	}
	for _, pos := range []int{0, 1, 25, 57, 57 + 1087, 1145, len(out) - 1} {
		tampered := append([]byte(nil), out...)
		tampered[pos] ^= 0x01
		if _, err := open(tampered, senderPK); err != ErrDHIESDecrypt {
			t.Errorf("tampered byte %d accepted", pos)
		}
	}
	if _, err := open(out[:DHIESV3MinSize-1], senderPK); err != ErrDHIESDecrypt {
		t.Error("truncated message accepted")
	}
	lowOrder := append([]byte(nil), out...)
	copy(lowOrder[25:57], make([]byte, 32))
	if _, err := open(lowOrder, senderPK); err != ErrDHIESDecrypt {
		t.Error("low-order ephemeral key accepted")
	}
	// a DHIES v2 message to the same X25519 key is not a v3 message
	v2, err := DHIESEncryptV2(senderSK, senderPK, recipient.Cypher.PublicKey, plaintext)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := open(v2, senderPK); err != ErrDHIESDecrypt {
		t.Error("DHIES v2 accepted by the v3 decryption")
	}

	// encryption input checks
	if _, err := DHIESEncryptV3(senderSK, senderPK, recipient.Cypher.PublicKey, ek[:1183], plaintext); err == nil {
		t.Error("short ML-KEM key accepted")
	}
	badEK := bytes.Repeat([]byte{0xff}, MLKEM768PublicKeySize) // coefficients >= q: fails the modulus check
	if _, err := DHIESEncryptV3(senderSK, senderPK, recipient.Cypher.PublicKey, badEK, plaintext); err == nil {
		t.Error("ML-KEM key failing the modulus check accepted")
	}
	if _, err := DHIESEncryptV3(senderSK, senderPK, make([]byte, 32), ek, plaintext); err == nil {
		t.Error("all-zero recipient X25519 key accepted")
	}
}

func TestDHIESV3IsRandomized(t *testing.T) {
	senderSK, senderPK, recipient := newPQPair(t)
	a, _ := DHIESEncryptV3(senderSK, senderPK, recipient.Cypher.PublicKey, recipient.GetKEMPublicKey(), []byte("x"))
	b, _ := DHIESEncryptV3(senderSK, senderPK, recipient.Cypher.PublicKey, recipient.GetKEMPublicKey(), []byte("x"))
	if bytes.Equal(a, b) || bytes.Equal(a[25:1145], b[25:1145]) {
		t.Error("two encryptions share their ephemeral key or KEM ciphertext")
	}
}

func TestPostQuantumDilithiumManager(t *testing.T) {
	entropy := make([]byte, 32)
	if _, err := rand.Read(entropy); err != nil {
		t.Fatal(err)
	}
	classical, _ := CreateDilithiumFromEntropyInternal(entropy)
	pq, _ := CreateDilithiumFromEntropyInternal(entropy)
	if err := pq.EnablePostQuantum(); err != nil {
		t.Fatal(err)
	}
	if classical.IsPostQuantum() || !pq.IsPostQuantum() {
		t.Fatal("IsPostQuantum")
	}
	// the PRF key replaces the X25519 secret in HMAC and getSecretHash
	h1, _ := classical.HMAC("m")
	h2, _ := pq.HMAC("m")
	s1, _ := classical.GetSecretHash([]byte("d"))
	s2, _ := pq.GetSecretHash([]byte("d"))
	if bytes.Equal(h1, h2) || bytes.Equal(s1, s2) {
		t.Error("post-quantum HMAC still keyed with the X25519 secret")
	}
	// {v, x, e, k}: 3826 bytes without the type byte
	id := pq.ToBytes()
	if len(id) != 3826 || len(classical.ToBytes()) != 2637 {
		t.Fatalf("id length %d", len(id))
	}
	parsed, err := PostQuantumFromID(id)
	if err != nil || !bytes.Equal(parsed.ToBytes(), id) || parsed.GetCapability() != "public" {
		t.Fatalf("PostQuantumFromID: %v", err)
	}
	if _, err := PostQuantumFromID(classical.ToBytes()); err == nil {
		t.Error("an id without k was accepted as post-quantum")
	}
	if _, err := parsed.HMAC("m"); err == nil {
		t.Error("public key manager computed an HMAC")
	}
	// SetVersion leaves a post-quantum key manager at version 1
	_ = pq.SetVersion(0)
	if pq.GetVersion() != 1 {
		t.Error("post-quantum key manager downgraded to version 0")
	}
	// the decapsulation key is re-derived and wiped with the seed
	pq.CleanSecureData()
	if _, err := pq.KEMDecapsulate(make([]byte, MLKEM768CiphertextSize)); err == nil {
		t.Error("decapsulation after CleanSecureData")
	}
	if _, err := pq.HMAC("m"); err == nil {
		t.Error("HMAC after CleanSecureData")
	}
}
